import unittest

from shop.pricing import average_price, bulk_total


class PricingTest(unittest.TestCase):
    def test_small_order_pays_full_price(self):
        self.assertEqual(bulk_total(2.0, 1), 2.0)

    def test_large_order_gets_ten_percent_off(self):
        self.assertEqual(bulk_total(1.0, 20), 18.0)

    def test_negative_qty_raises(self):
        with self.assertRaises(ValueError):
            bulk_total(1.0, -1)

    def test_average_of_three(self):
        self.assertEqual(average_price([1.0, 2.0, 3.0]), 2.0)

    def test_average_of_empty_list_is_zero(self):
        self.assertEqual(average_price([]), 0.0)


if __name__ == '__main__':
    unittest.main()

